option.value:
.grile-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.75rem;
  width: 100%;
  max-width: 1120px;
  margin: 0 auto;
}

.grile-card {
  width: 100%;
  background: #1e2233;
  border: 1px solid #2d3555;
  border-radius: 20px;
  padding: clamp(1.4rem, 2.5vw, 2.4rem);
  box-shadow: 0 4px 32px rgba(0, 0, 0, 0.4);
}

.grile-card-centered {
  text-align: center;
}

.grile-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.grile-header-stack {
  flex-wrap: wrap;
}

.grile-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #0ea5a0;
  color: white;
  font-size: 0.84rem;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.9rem;
}

.grile-title {
  font-size: clamp(1.35rem, 1.05rem + 0.9vw, 1.95rem);
  color: #eef2ff;
  line-height: 1.4;
  margin-bottom: 0.6rem;
}

.grile-subtitle {
  color: #94a3b8;
  line-height: 1.65;
  font-size: 0.98rem;
}

.grile-progress-box,
.grile-score-box {
  min-width: 140px;
  padding: 1rem 1.1rem;
  border-radius: 16px;
  background: #161929;
  border: 1px solid #2d3555;
  text-align: center;
}

.grile-progress-count,
.grile-score-value {
  display: block;
  font-size: 1.5rem;
  font-weight: 800;
  color: #e2e8f0;
}

.grile-progress-label,
.grile-score-label {
  display: block;
  margin-top: 0.35rem;
  color: #64748b;
  font-size: 0.84rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.grile-progress-bar {
  width: 100%;
  height: 10px;
  background: #161929;
  border-radius: 999px;
  overflow: hidden;
  margin-bottom: 1.5rem;
}

.chapter-filter-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 1.25rem;
}

.chapter-filter-label {
  color: #cbd5e1;
  font-weight: 700;
}

.chapter-filter-select {
  appearance: none;
  background: #161929;
  border: 1px solid #2d3555;
  color: #e2e8f0;
  border-radius: 10px;
  padding: 0.55rem 0.8rem;
  min-width: 220px;
  font-size: 0.95rem;
}

.chapter-filter-select:focus {
  outline: 2px solid rgba(20, 184, 166, 0.5);
  outline-offset: 2px;
}

.chapter-filter-count {
  color: #94a3b8;
  font-size: 0.92rem;
}

.grile-progress-bar-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #14b8a6, #3b82f6);
}

.quiz-options {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  width: 100%;
}

.quiz-option {
  display: grid;
  grid-template-columns: 20px 32px minmax(0, 1fr);
  align-items: flex-start;
  gap: 0.9rem;
  width: 100%;
  background: #161929;
  border: 1px solid #2d3555;
  border-radius: 16px;
  padding: 1rem 1.1rem;
  cursor: pointer;
  transition: border-color 0.2s ease, transform 0.15s ease, background 0.2s ease;
}

.quiz-option:hover {
  border-color: #4c5dd7;
  transform: translateY(-1px);
}

.quiz-option-selected {
  border-color: #14b8a6;
  background: rgba(20, 184, 166, 0.12);
}

.quiz-option-correct {
  border-color: rgba(34, 197, 94, 0.7);
  background: rgba(34, 197, 94, 0.14);
}

.quiz-option-wrong {
  border-color: rgba(248, 113, 113, 0.7);
  background: rgba(248, 113, 113, 0.12);
}

.quiz-option input {
  margin-top: 0.2rem;
  accent-color: #14b8a6;
  width: 18px;
  height: 18px;
}

.quiz-option-letter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #252d4a;
  color: #cbd5e1;
  font-weight: 700;
  flex-shrink: 0;
}

.quiz-option-text {
  display: block;
  width: 100%;
  color: #dbe4ff;
  line-height: 1.6;
  white-space: normal;
  word-break: break-word;
}

.quiz-feedback {
  margin-top: 1.2rem;
  border-radius: 16px;
  border: 1px solid #2d3555;
  padding: 1rem 1.1rem;
  background: #161929;
}

.quiz-feedback-correct {
  border-color: rgba(34, 197, 94, 0.7);
  background: rgba(34, 197, 94, 0.1);
}

.quiz-feedback-wrong {
  border-color: rgba(248, 113, 113, 0.7);
  background: rgba(248, 113, 113, 0.08);
}

.quiz-feedback-pending {
  border-color: rgba(14, 165, 160, 0.45);
  background: rgba(14, 165, 160, 0.08);
}

.quiz-feedback-header {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  margin-bottom: 0.9rem;
}

.quiz-feedback-badge {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.45);
  color: #f8fafc;
  padding: 0.35rem 0.75rem;
  font-size: 0.84rem;
  font-weight: 700;
}

.quiz-feedback-title {
  color: #eef2ff;
  font-size: 1rem;
  font-weight: 700;
}

.quiz-feedback-block + .quiz-feedback-block {
  margin-top: 0.85rem;
}

.quiz-feedback-block p {
  color: #94a3b8;
  font-weight: 600;
  margin-bottom: 0.4rem;
}

.quiz-feedback-block ul {
  padding-left: 1.2rem;
  color: #dbe4ff;
}

.quiz-feedback-block li + li {
  margin-top: 0.25rem;
}

.quiz-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1rem;
  margin-bottom: 1.4rem;
}

.quiz-stat {
  background: #161929;
  border: 1px solid #2d3555;
  border-radius: 16px;
  padding: 1rem 1.1rem;
}

.quiz-stat-value {
  display: block;
  font-size: 1.45rem;
  font-weight: 800;
  color: #e2e8f0;
}

.quiz-stat-label {
  display: block;
  margin-top: 0.35rem;
  color: #64748b;
  font-size: 0.9rem;
}

.quiz-actions {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.quiz-actions-bottom {
  margin-top: -0.5rem;
}

.nav-btn-secondary {
  background: #252d4a;
}

.nav-btn-secondary:hover:not(:disabled) {
  background: #33406b;
}

.nav-btn-warning {
  background: #b45309;
}

.nav-btn-warning:hover:not(:disabled) {
  background: #d97706;
}

.dot-answered {
  background: #14b8a6;
}

.quiz-review-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-top: 1.5rem;
}

.quiz-review-card {
  border-radius: 16px;
  border: 1px solid #2d3555;
  background: #161929;
  padding: 1rem 1.1rem;
}

.quiz-review-correct {
  border-color: rgba(34, 197, 94, 0.55);
}

.quiz-review-wrong {
  border-color: rgba(248, 113, 113, 0.55);
}

.quiz-review-pending {
  border-color: rgba(14, 165, 160, 0.45);
}

.quiz-review-top {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
  margin-bottom: 0.75rem;
}

.quiz-review-index,
.quiz-review-status {
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.quiz-review-index {
  color: #93c5fd;
}

.quiz-review-status {
  color: #cbd5e1;
}

.quiz-review-question {
  color: #eef2ff;
  font-size: 1.05rem;
  line-height: 1.5;
  margin-bottom: 0.8rem;
}

.quiz-review-note {
  color: #93c5fd;
  line-height: 1.5;
}

.quiz-review-block + .quiz-review-block {
  margin-top: 0.9rem;
}

.quiz-review-block p {
  color: #94a3b8;
  font-weight: 600;
  margin-bottom: 0.4rem;
}

.quiz-review-block ul {
  padding-left: 1.2rem;
  color: #dbe4ff;
}

.quiz-review-block li + li {
  margin-top: 0.3rem;
}

.quiz-review-empty {
  color: #fca5a5;
}

@media (max-width: 720px) {
  .chapter-filter-row {
    align-items: stretch;
  }

  .chapter-filter-select {
    width: 100%;
    min-width: 0;
  }

  .quiz-option {
    grid-template-columns: 20px 28px minmax(0, 1fr);
  }

  .quiz-option-letter {
    width: 28px;
    height: 28px;
  }

  .grile-progress-box,
  .grile-score-box {
    width: 100%;
  }

  .quiz-review-top {
    flex-direction: column;
    align-items: flex-start;
  }
}

